<div class="section-heading"><div><div class="eyebrow"><?=$platform?'Central da plataforma':'Atendimento'?></div><h1><?=$platform?'Suporte aos clientes':'Suporte'?></h1><p class="text-secondary mb-0"><?=$platform?'Veja chamados e entre em acesso assistido quando o cliente autorizar.':'Abra chamados e, se necessário, autorize temporariamente o suporte a acessar seu painel.'?></p></div></div>
<?php if(!$platform):?><div class="card mb-4"><div class="card-body"><form method="post" action="/support" class="row g-3"><?php echo \App\Core\CSRF::field();?><div class="col-md-3"><select class="form-select" name="category"><option value="technical">Problema técnico</option><option value="question">Dúvida</option><option value="billing">Financeiro</option><option value="integration">Integração</option><option value="suggestion">Sugestão</option><option value="other">Outro</option></select></div><div class="col-md-6"><input class="form-control" name="subject" placeholder="Assunto" required></div><div class="col-md-3"><select class="form-select" name="priority"><option value="normal">Normal</option><option value="high">Alta</option><option value="urgent">Urgente</option></select></div><div class="col-12"><textarea class="form-control" name="description" minlength="10" rows="4" placeholder="Explique o que está acontecendo" required></textarea></div><div class="col-md-5"><input class="form-control" name="error_id" placeholder="Código do erro (ex.: ERR-20260807-87D8B9)"></div><input type="hidden" name="source_url" value="<?=htmlspecialchars($_SERVER['HTTP_REFERER']??$_SERVER['REQUEST_URI']??'')?>"><input type="hidden" name="browser_context" value="<?=htmlspecialchars($_SERVER['HTTP_USER_AGENT']??'')?>"><input type="hidden" name="app_version" value="<?=htmlspecialchars((require __DIR__.'/../../../config/app.php')['version']??'4.0.0 RC')?>"><div class="col-12"><label class="form-check"><input class="form-check-input" type="checkbox" name="remote_access" value="1"> Autorizo o suporte a acessar temporariamente meu painel para analisar este chamado.</label><small class="text-secondary">O acesso fica vinculado ao chamado, é auditado e pode ser revogado.</small></div><div><button class="btn btn-primary">Abrir chamado</button></div></form></div></div><?php endif;?>
<div class="card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Protocolo</th><?php if($platform):?><th>Empresa</th><?php endif;?><th>Assunto</th><th>Prioridade</th><th>Acesso</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($tickets as $t):?><tr><td><strong><?=htmlspecialchars($t['protocol'])?></strong></td><?php if($platform):?><td><?=htmlspecialchars($t['tenant_name']??'')?></td><?php endif;?><td><?=htmlspecialchars($t['subject'])?></td><td><?=htmlspecialchars(['low'=>'Baixa','normal'=>'Normal','high'=>'Alta','urgent'=>'Urgente'][$t['priority']]??$t['priority'])?></td><td><?=$t['remote_access_allowed']?'<span class="badge text-bg-success">Autorizado</span>':'<span class="badge text-bg-light">Não autorizado</span>'?></td><td><?=htmlspecialchars(['open'=>'Aberto','in_progress'=>'Em atendimento','waiting_user'=>'Aguardando cliente','resolved'=>'Resolvido','closed'=>'Fechado'][$t['status']]??$t['status'])?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="/support/<?=(int)$t['id']?>">Abrir</a></td></tr><?php endforeach;?><?php if(!$tickets):?><tr><td colspan="7"><div class="empty-state">Nenhum chamado encontrado.</div></td></tr><?php endif;?></tbody></table></div></div>
